/**
 * Muestra un menú contextual simulado al hacer clic derecho sobre una celda editable.
 * @param {HTMLElement} target - El elemento <td> donde se hizo clic derecho.
 */
function showContextMenu(target) {
    // Prevenir el menú de contexto nativo del navegador
    event.preventDefault(); 

    const menu = document.createElement('div');
    menu.className = 'context-menu';
    menu.style.position = 'absolute';
    menu.style.left = `${event.clientX}px`;
    menu.style.top = `${event.clientY}px`;
    menu.innerHTML = `
        <button class="context-btn" data-action="color">🎨 Color de Fondo</button>
        <!-- Otras opciones podrían ir aquí -->
    `;

    document.body.appendChild(menu);

    // Añadir evento para seleccionar color
    const colorButton = menu.querySelector('[data-action="color"]');
    if (colorButton) {
        colorButton.addEventListener('click', function() {
            const colorHex = prompt("Introduce el código hexadecimal del color (ej: #FF0000):", "#FFFF00");
            if (colorHex) {
                handleColorChange(target, colorHex);
                guardar(); // Guardamos cualquier cambio visual que se considere parte del estado de la sesión.
            }
            menu.remove();
        });
    }

    // Cerrar menú al hacer click fuera
    document.addEventListener('click', function handler(e) {
        if (!menu.contains(e.target)) {
            menu.remove();
            document.removeEventListener('click', handler);
        }
    }, { once: true });
}
