function showContextMenu(event, cellElement) {
    // 1. Crear o encontrar el menú de contexto
    let contextMenu = document.getElementById('context-menu');
    if (!contextMenu) {
        contextMenu = document.createElement('div');
        contextMenu.id = 'context-menu';
        contextMenu.className = 'context-menu';
        document.body.appendChild(contextMenu);
    }

    // 2. Limpiar contenido previo y mostrar opciones relevantes para la celda
    contextMenu.innerHTML = '';
    const options = [
        { label: "Cambiar color de fondo...", action: 'bgcolor' }
    ];

    options.forEach(option => {
        const item = document.createElement('div');
        item.textContent = option.label;
        item.dataset.action = option.action;
        contextMenu.appendChild(item);
    });

    // 3. Posicionar el menú en la posición del clic, pero ajustado al cursor.
    const menuWidth = contextMenu.offsetWidth;
    const menuHeight = contextMenu.offsetHeight;

    // Ajustar la posición para que no se salga de la ventana
    let x = event.clientX;
    let y = event.clientY;

    if (x + menuWidth > window.innerWidth) {
        x = window.innerWidth - menuWidth - 10;
    }
    if (y + menuHeight > window.innerHeight) {
        y = window.innerHeight - menuHeight - 10;
    }

    contextMenu.style.left = `${x}px`;
    contextMenu.style.top = `${y}px`;
    contextMenu.style.display = 'block';
}
