function handleColumnSelection(columnLetter) {
    // Limpiar selección previa y deshabilitar controles
    document.querySelectorAll('.col-header').forEach(th => th.classList.remove('selected'));
    document.getElementById('column-controls').innerHTML = '';

    if (window.selectedColumn) {
        window.selectedColumn.classList.remove('selected');
    }

    // Establecer nueva selección y actualizar UI
    const selectedHeader = document.querySelector(`.col-header:has(span[data-letter="${columnLetter}"])`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
        window.selectedColumn = selectedHeader;

        // Generar controles de acción
        const controlsDiv = document.getElementById('column-controls');
        controlsDiv.innerHTML = `
            <button id="clear-col-btn" class="action-btn">🗑️ Vaciar Columna ${columnLetter}</button>
            <button id="bg-color-col-btn" class="action-btn">🎨 Fondo Columna ${columnLetter}</button>
            <button id="delete-col-btn" class="action-btn danger">❌ Borrar Columna ${columnLetter}</button>
        `;

        // Asignar listeners a los nuevos botones
        document.getElementById('clear-col-btn').addEventListener('click', () => {
            handleClearColumn(columnLetter);
        });

        document.getElementById('bg-color-col-btn').addEventListener('click', () => {
            handleBackgroundColorChange(columnLetter);
        });

        document.getElementById('delete-col-btn').addEventListener('click', () => {
            if (confirm(`¿Está seguro de que desea borrar la columna ${columnLetter}? ¡Esta acción es irreversible!`)) {
                handleDeleteColumn(columnLetter);
            }
        });
    }
}
