function handleDeleteColumn(columnLetter) {
    // 1. Borrar el contenido y las referencias del estado global (estado).
    const keysToDelete = [];
    for (let i = 1; i <= 20; i++) {
        const key = `${columnLetter}${i}`;
        keysToDelete.push(key);
    }

    keysToDelete.forEach(key => {
        delete estado[key];
    });

    // 2. Borrar la estructura física (TH y TDs) del DOM.

    // A. Eliminar el header de la columna
    const headerToRemove = document.querySelector(`.col-header span[data-letter="${columnLetter}"]`).closest('th');
    if (headerToRemove) {
        headerToRemove.remove();
    }

    // B. Eliminar todas las celdas TD correspondientes en el cuerpo de la tabla.
    const cellsToRemove = document.querySelectorAll(`td[data-cell^="${columnLetter}"]`);
    cellsToRemove.forEach(cell => cell.remove());


    guardar();
    render(); // Re-renderizar para limpiar cualquier residuo y asegurar que la vista coincida con el estado vacío.
}
