### FUNCION: deleteSelectedColumn
```js
function deleteSelectedColumn() {
    if (!selectedColumn) return;
    const letter = selectedColumn;

    if (!confirm(`¿Está seguro que desea eliminar permanentemente la columna ${letter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Identificar todas las claves afectadas y eliminarlas del estado
    let keysToDelete = [];
    for (const key in estado) {
        if (key.toUpperCase().startsWith(letter.toUpperCase()) && key !== 'A1') { // Excluimos A1 por si es una fórmula crítica, pero borramos el resto.
            keysToDelete.push(key);
        }
    }

    // 2. Eliminar las claves del estado
    keysToDelete.forEach(key => delete estado[key]);

    // 3. Limpiar DOM y actualizar la estructura de la tabla
    const columnCells = document.querySelectorAll(`td[data-cell^="${letter}"]`);
    columnCells.forEach(cell => {
        cell.remove();
    });

    // 4. Reajustar el thead (eliminar el encabezado)
    const headerTh = document.querySelector(`.col-header[data-column-letter="${letter}"]`);
    if (headerTh) {
        headerTh.remove();
    }

    // 5. Re-renderizar la estructura para reajustar anchos y asegurar que el estado esté limpio
    guardar();
    render();
}
```

### FUNCION: connectColumnListeners
```js
function connectColumnListeners() {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // 1. Listener para hacer clic en los encabezados de columna (A, B, C...)
    container.addEventListener('click', function(event) {
        const target = event.target;
        if (target && target.classList.contains('col-header')) {
            selectColumn(target.getAttribute('data-column-letter'));
        }
    });

    // 2. Listener para los botones de acción en el panel de control
    document.getElementById('clear-col-btn').addEventListener('click', clearSelectedColumn);
    document.getElementById('color-col-btn').addEventListener('click', changeBackgroundColorColumn);
    document.getElementById('delete-col-btn').addEventListener('click', deleteSelectedColumn);
}
