### FUNCION: handleColumnAction
```js
function handleColumnAction(action, letter) {
    if (!estado.selectedColumn || estado.selectedColumn !== letter) {
        console.error("No se ha seleccionado la columna o el evento no coincide.");
        return;
    }

    switch (action) {
        case 'clear':
            clearColumnContent(letter);
            break;
        case 'color':
            const color = prompt("Introduce el código de color (#rrggbb):");
            if (color && /^#[0-9a-f]{6}$/i.test(color)) {
                applyBackgroundColors(letter, color);
            } else if (color !== null) {
                 alert("Formato de color inválido. Debe ser #rrggbb.");
            }
            break;
        case 'delete':
            if (!confirm(`¿Estás seguro que deseas eliminar la columna ${letter}? Esta acción es irreversible.`)) {
                return;
            }
            deleteColumn(letter);
            break;
    }

    // Después de cualquier acción, guardar el estado y redibujar para reflejar los cambios.
    guardar();
    render();
}
```

