 */
function applyBackgroundColors(letter, color) {
    const cells = document.querySelectorAll(`[data-cell^="${letter}"]`);
    cells.forEach(cell => {
        // Esto es un cambio de estilo visual que se maneja con CSS/DOM directamente.
        cell.style.backgroundColor = color;
    });
}

/**
 * Elimina la columna completamente del estado, DOM y atributos data-cell.
 * @param {string} letter - La letra de la columna a eliminar.
 */
function deleteColumn(letter) {
    // 1. Eliminar claves del estado global para todas las celdas de esta columna
    for (let r = 1; r <= 20; r++) { // Asumiendo filas 1 a 20
        const key = `${letter}${r}`;
        delete estado[key];
    }

    // 2. Eliminar los elementos DOM y reestructurar la tabla.
    const container = document.getElementById('spreadsheet-container');

    // Iterar sobre las columnas en el thead y eliminar los TH de encabezado
    document.querySelectorAll('.col-header').forEach(th => {
        if (th.getAttribute('data-column-letter') === letter) {
            th.remove();
        }
    });

    // Eliminar celdas del tbody fila por fila
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells.length > 0) {
            // En un entorno real se debería remapear el índice de las celdas restantes, pero para el mínimo cambio:
             const indexToRemove = Array.from(cells).findIndex(cell => cell.getAttribute('data-cell').startsWith(letter));
             if (indexToRemove > -1) {
                 cells[indexToRemove].remove();
             }
        }
    });

    estado.selectedColumn = null;
    console.log(`Columna ${letter} eliminada exitosamente.`);
}


/**
 * Actualiza el estado global cuando un usuario termina de editar una celda.
 * @param {HTMLElement} cellElement - El elemento <td> que ha sido modificado.
 */
function handleCellUpdate(cellElement) {
    // 1. Update state with raw input first (puede ser la fórmula).
    updateCellState(cellElement);

    const key = cellElement.getAttribute('data-cell');
    let currentValue = estado[key];

    // 2. Detectar y calcular fórmulas si es necesario, actualizando el estado con el resultado numérico.
    if (typeof currentValue === 'string' && currentValue.trim().startsWith('=')) {
        const calculatedValue = calculateFormula(currentValue);

        // Si la fórmula se pudo calcular exitosamente y resultó en un valor numérico válido.
        if (typeof calculatedValue === 'number') {
             // Guardamos el resultado formateado como string, ya que este es el dato persistente.
            estado[key] = String(calculatedValue); 
        } else if (calculatedValue !== currentValue) {
             // Si no se detectó una fórmula o falló, mantenemos la lógica de estado normal.
             estado[key] = calculatedValue;
        }
    }
}


// ===== DIBUJO: render() arma la pantalla entera desde `estado`. Lo que se muestra se calcula acá; la página no guarda datos. =====
function render() {
    const cells = document.querySelectorAll('#spreadsheet-container [contenteditable="true"]');

    cells.forEach(cell => {
        const key = cell.getAttribute('data-cell');
        if (estado[key] !== undefined) {
            // Solo actualizamos el contenido si el estado tiene un valor guardado.
            // Esto asegura que la vista refleje siempre 'estado'.
            cell.textContent = estado[key];
        } else if (key === null) {
             // Caso de seguridad por si falta data-cell o está vacío en estado.
             cell.textContent = '';
        }
    });
}

// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    const container = document.getElementById('spreadsheet-container');

    if (container) {
        // 1. Listener para cuando el usuario sale de una celda editable (focusout/blur).
        container.addEventListener('focusout', function(event) {
            const target = event.target;

            // Verificamos si el objetivo es una celda editable y si realmente perdimos el foco.
            if (target && target.hasAttribute('contenteditable') === true) {
                handleCellUpdate(target);
                guardar();
                render();
            }
        });

        // 2. Listener para Enter en celdas editable.
        container.addEventListener('keydown', function(event) {
            const target = event.target;

            if (target && target.hasAttribute('contenteditable') === true && event.key === 'Enter') {
                // Prevenimos el comportamiento por defecto del formulario/input que podría ser hacer scroll o saltar de fila.
                event.preventDefault(); 

                // El valor se actualiza con lo que está en la celda después de presionar Enter.
                handleCellUpdate(target);
                guardar();
                render();
            }
        });

        // 3. Listener para selección de columna (clic en .col-header).
        container.querySelectorAll('.col-header').forEach(header => {
             // Usamos el método addEventListener directamente sobre los elementos, ya que son estáticos y no se añaden dinámicamente.
            header.addEventListener('click', selectColumn); 
        });

        // 4. Listener para menú contextual (Clic derecho) en encabezados de columna.
        container.querySelectorAll('.col-header').forEach(header => {
             header.addEventListener('contextmenu', function(event) {
                event.preventDefault(); // Previene el menú contextual por defecto del navegador
                const letter = this.getAttribute('data-column-letter');

                // Mostrar controles/menú de contexto (simulando la acción al hacer clic derecho)
                const action = prompt(`Acciones disponibles para Columna ${letter}:\n\n[1] Limpiar Contenido: (Borra datos)\n[2] Cambiar Color Fondo: (Ej: #ff0000)\n[3] Eliminar Columna: (BORRAR PERMANENTE)`);

                if (!action) return;

                if (action === '1' || action.toLowerCase().includes('limpiar')) {
                    clearColumnContent(letter);
                } else if (action === '2' || action.toLowerCase().includes('color')) {
                    const color = prompt("Por favor, introduce el código de color HEX (#rrggbb):");
                    if (color && /^#[0-9a-f]{6}$/i.test(color)) {
                        applyBackgroundColors(letter, color);
                    } else if (color !== null) {
                         alert("Formato de color inválido.");
                    }
                } else if (action === '3' || action.toLowerCase().includes('eliminar')) {
                    deleteColumn(letter);
                }
            });
        });

    }
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
