function conectar() {
    const container = document.getElementById('spreadsheet-container');
    const headersRow = document.querySelector('#spreadsheet-container thead tr');
    const actionPanel = document.getElementById('column-actions');

    // 1. Listener para seleccionar columna (Headers)
    if (headersRow) {
        headersRow.addEventListener('click', function(event) {
            const target = event.target;
            if (target && target.classList.contains('column-header-letter') && target.dataset.columnLetter) {
                selectColumn(target.dataset.columnLetter);
            }
        });
    }

    // 2. Listener para cuando el usuario sale de una celda editable (focusout/blur).
    container.addEventListener('focusout', function(event) {
        const target = event.target;

        // Verificamos si el objetivo es una celda editable y si realmente perdimos el foco.
        if (target && target.hasAttribute('contenteditable') === true) {
            handleCellUpdate(target);
            guardar();
            render();
        }
    });

    // 3. Listener para Enter en celdas editable.
    container.addEventListener('keydown', function(event) {
        const target = event.target;

        if (target && target.hasAttribute('contenteditable') === true && event.key === 'Enter') {
            // Prevenimos el comportamiento por defecto del formulario/input que podría ser hacer scroll o saltar de fila.
            event.preventDefault(); 

            // El valor se actualiza con lo que está en la celda después de presionar Enter.
            handleCellUpdate(target);
            guardar();
            render();
        }
    });

    // 4. Listeners para los controles de columna (solo si el panel existe)
    if (!document.getElementById('delete-col-btn')) return; // Evita duplicación en reinicios

    document.getElementById('apply-color-btn').addEventListener('click', () => {
        const selectedLetter = getSelectedColumn();
        if (selectedLetter) {
            const color = document.getElementById('color-picker').value;
            applyBackgroundColor(selectedLetter, color);
        }
    });

    document.getElementById('clear-col-btn').addEventListener('click', () => {
        const selectedLetter = getSelectedColumn();
        if (selectedLetter) {
            clearColumnContents(selectedLetter);
        }
    });

    document.getElementById('delete-col-btn').addEventListener('click', () => {
        const selectedLetter = getSelectedColumn();
        if (selectedLetter && confirm(`¿Estás seguro de que quieres eliminar la columna ${selectedLetter}? Esto borrará todos sus datos.`)) {
            deleteColumn(selectedLetter);
        }
    });
}
