### FUNCION: clearColumn
```js
/**
 * Borra el contenido de todas las celdas en la columna especificada.
 * @param {string} letter - La letra de la columna (ej: 'A', 'B').
 */
function clearColumn(letter) {
    // Encontramos la fila máxima existente en esta columna para saber qué celdas limpiar.
    let maxRow = 0;
    const keysInColumn = Object.keys(estado).filter(key => key.toUpperCase().startsWith(letter.toUpperCase()));

    if (keysInColumn.length === 0) {
        return; // No hay datos en esta columna para borrar.
    }

    // Determinamos la fila más alta que tiene contenido o ha sido referenciada.
    for (const key of keysInColumn) {
        const match = key.match(/([A-Z]+)([0-9]+)/);
        if (match && parseInt(match[2]) > maxRow) {
            maxRow = parseInt(match[2]);
        }
    }

    // Limpiamos el estado para todas las celdas de la columna hasta la fila máxima.
    for (let r = 1; r <= maxRow; r++) {
        const key = `${letter}${r}`;
        estado[key] = ''; // Establece el valor en vacío, borrando el contenido del estado.
    }
}
