/**
 * Cambia el color de fondo de todas las celdas en una columna dada.
 * @param {string} colLetter - La letra de la columna (ej: 'A').
 * @param {string} color - El código de color CSS (ej: '#ffcccc').
 */
function setColorColumn(colLetter, color) {
