/**
 * Elimina completamente una columna del estado, el DOM y la estructura de datos.
 * @param {string} colLetter - La letra de la columna a eliminar (ej: 'A').
 */
function deleteColumn(colLetter) {
    // 1. Limpiar el estado para esa columna
    for (const key in estado) {
        if (key[0].toUpperCase() === colLetter.toUpperCase()) {
            delete estado[key];
        }
    }

    // 2. Eliminar elementos del DOM asociados a esta columna
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // Selecciona todos los elementos de celda que pertenecen a esta columna.
    const selector = `[data-cell^="${colLetter}"]`;
    const elementsToRemove = container.querySelectorAll(selector);

    elementsToRemove.forEach(el => el.remove());

    // 3. Re-renderizar para asegurar la consistencia del DOM y los encabezados.
    render();
    guardar();
}
