### FUNCION: selectRowLogic
```js
/**
 * Selecciona una fila específica por su ID y actualiza tanto la UI como el estado interno.
 * @param {string} rowId - El número de fila a seleccionar (ej: "3").
 */
function selectRowLogic(rowId) {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // 1. Deseleccionar la fila previamente seleccionada
    let currentlySelectedRowElement = container.querySelector('.selected-row');
    if (currentlySelectedRowElement) {
        currentlySelectedRowElement.classList.remove('selected-row');
    }

    // 2. Encontrar la nueva fila y seleccionarla
    const newRowElement = document.getElementById(`row-${rowId}`);
    if (newRowElement && !newRowElement.classList.contains('selected-row')) {
        newRowElement.classList.add('selected-row');
        estado.selectedRowId = rowId;
        console.log(`Fila ${rowId} seleccionada.`);
        // Aquí podríamos emitir un evento de selección si hubiera componentes externos dependientes.
    } else {
         // Si la fila no existe o ya está seleccionada, simplemente actualizamos el estado sin cambiar UI.
        estado.selectedRowId = rowId;
    }
}

/**
 * Borra completamente la fila actualmente seleccionada del DOM y del estado (si es necesario).
 */
function deleteSelectedRowLogic() {
    const rowId = estado.selectedRowId;
    if (!rowId) return alert("Por favor, selecciona una fila para eliminar.");

    // 1. Confirmación de borrado
    if (!confirm(`¿Está seguro de que desea borrar la fila ${rowId}? Esta acción es irreversible.`)) {
        return;
    }

    const rowElement = document.getElementById(`row-${rowId}`);
    if (rowElement) {
        // 2. Eliminar el elemento del DOM
        rowElement.remove();

        // 3. Limpiar el estado de selección y guardar los cambios.
        estado.selectedRowId = null;
        guardar();
        render(); // Redibujar para limpiar cualquier rastro visual/funcional.
    } else {
        alert(`Error: No se encontró la fila ${rowId}.`);
    }
}

/**
 * Borra el contenido de todas las celdas dentro de la fila seleccionada, manteniendo la estructura.
 */
function clearSelectedRowContentLogic() {
    const rowId = estado.selectedRowId;
    if (!rowId) return alert("Por favor, selecciona una fila para limpiar su contenido.");

    // 1. Recorrer todas las celdas de la fila seleccionada (excepto el selector de número).
    const rowElement = document.getElementById(`row-${rowId}`);
    if (!rowElement) return;

    const cells = rowElement.querySelectorAll('td[contenteditable="true"]');
    let clearedCount = 0;

    cells.forEach(cell => {
        const key = cell.getAttribute('data-cell');
        // 2. Limpiar el estado y la UI de cada celda.
        estado[key] = '';
        cell.textContent = '';
        clearedCount++;
    });

    guardar();
    render(); // Redibujar para asegurar que cualquier cálculo dependiente se actualice a vacío.
}

/**
 * Cambia el color de fondo de todas las celdas dentro de la fila seleccionada y aplica la clase visual.
 */
function changeSelectedRowColorLogic() {
    const rowId = estado.selectedRowId;
    if (!rowId) return alert("Por favor, selecciona una fila para cambiar su color.");

    // 1. Recorrer todas las celdas de la fila seleccionada (excepto el selector de número).
    const rowElement = document.getElementById(`row-${rowId}`);
    if (!rowElement) return;

    const cells = rowElement.querySelectorAll('td[contenteditable="true"]');

    // 2. Aplicar clases CSS para el cambio de color visual (el estilo se gestiona en la UI).
    cells.forEach(cell => {
        cell.classList.add('highlight-bg'); // Añadir clase base si no existe
        // Nota: Si tuviéramos un estado de color, lo actualizaríamos aquí. Como solo es una acción visual, basta con manipular el DOM/CSS.
    });

    guardar();
    render(); 
}
