                let rowNumberText = '';

                // Intentar encontrar un texto numérico dentro del clic (ej: 1, 2, ...)
                if(target.textContent && !isNaN(parseInt(target.textContent))) {
                    rowNumberText = target.textContent;
                } else if(target.parentNode) {
                     // Si el click es en la celda que contiene el número
