        return;
    }

    // Seleccionar todas las celdas (<td>) en esa fila.
    const cellsInRow = Array.from(rowElement.querySelectorAll('td[contenteditable="true"]'));

    // Mostrar un menú contextual o simplemente ejecutar la acción si el click fue directo en el número.
    // Para simplificar, asumiremos que el usuario quiere borrar contenido por defecto al hacer clic.

